/* HomeFit runs directly from a local file. No network requests or runtime dependencies. */
(()=>{
 'use strict';
 const H=HomeFit,D=HomeFitData,KEY='homefit.v1',app=document.querySelector('#app'),modal=document.querySelector('#modal');
 const paths={calendar:'M4 5h16v16H4ZM4 10h16M8 3v4M16 3v4',home:'M3 10 12 3l9 7v11h-6v-8H9v8H3Z',workout:'M6 8v8M3 9v6m15-7v8m3-7v6M6 12h12',library:'m3 7 9-4 9 4-9 4Zm0 5 9 4 9-4M3 17l9 4 9-4',progress:'M4 21v-6m5 6V9m5 12V5m5 16V2',profile:'M20 21v-2a6 6 0 0 0-6-6h-4a6 6 0 0 0-6 6v2ZM16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',arrow:'M4 12h15m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L20 5',close:'m6 6 12 12M6 18 18 6',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',swap:'M3 7h16m-4-4 4 4-4 4M21 17H5m4-4-4 4 4 4',pause:'M8 5v14M16 5v14',play:'m8 4 12 8-12 8Z',leaf:'M20 3C7 1 1 8 5 16s18 3 15-13ZM5 20 16 8',shield:'m12 2 9 4v7c0 6-9 9-9 9s-9-3-9-9V6Zm-5 10 3 3 7-7',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',target:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M18 12a6 6 0 1 1-12 0 6 6 0 0 1 12 0M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0',info:'M12 11v6M12 7v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
 const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.workout}"/></svg>`;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const cap=s=>s.charAt(0).toUpperCase()+s.slice(1);
 const labels={full:'Full body',upper:'Upper body',lower:'Lower body',core:'Core',legs:'Legs',glutes:'Glutes',chest:'Chest',back:'Back',shoulders:'Shoulders',arms:'Arms',bodyweight:'Bodyweight',bands:'Resistance bands',long:'Long resistance band',mini:'Mini loop band',dumbbells:'Dumbbells',mat:'Exercise mat',fitness:'Everyday fitness',strength:'Build strength',endurance:'Muscular endurance',knees:'Knee-sensitive',wrists:'Wrist-sensitive',floor:'Avoid floor exercises',impact:'Low impact only'};
 const label=s=>labels[s]||cap(s);
 const equipmentLabel=e=>label(e.bandType||e.equipment);
 const bandConfirmation=p=>p.equipment.includes('bands')&&!(p.bandTypes||[]).length;
 const fmt=s=>`${String(Math.floor(Math.max(0,s)/60)).padStart(2,'0')}:${String(Math.floor(Math.max(0,s)%60)).padStart(2,'0')}`;
 const date=s=>new Date(s).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
 let planIssue=null;
 let storageError='',state=H.fresh(),route='today',seed=0,lastFocus=null,library={query:'',muscle:'all',equipment:'all',compatible:false};
 try{const raw=localStorage.getItem(KEY);if(raw){state=H.loadState(JSON.parse(raw));if(!JSON.parse(raw).revision&&!localStorage.getItem('homefit.v1.pre-v2'))localStorage.setItem('homefit.v1.pre-v2',raw);}}catch(e){storageError='Your saved data could not be read. It has not been overwritten. Export the stored data from My profile before choosing to reset it.';}
 let recovered=!!state.active;
 if(state.active){state.active.paused=true;state.active.deadline=null;state.active.lastTick=Date.now();}
 let writeBlocked=!!storageError;
 function save(){if(writeBlocked)return false;try{localStorage.setItem(KEY,JSON.stringify(state));storageError='';return true;}catch(e){storageError='Local storage is unavailable or full. Changes are only in memory. Export a backup before closing HomeFit.';toast(storageError);return false;}}
 function toast(text){if(storageError&&text!==storageError)text=storageError;const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4200);}
 const btn=(text,action,cls='secondary',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
 function demo(id,animate=true){
   const e=H.byId(id)||H.byId('squat'),a=D.poses[e.poses[0]],b=D.poses[e.poses[1]];
   const anim=(attr,values)=>animate?`<animate attributeName="${attr}" values="${values}" dur="4s" repeatCount="indefinite" calcMode="spline" keyTimes="0;.45;.55;1" keySplines=".4 0 .2 1;0 0 1 1;.4 0 .2 1"/>`:'';
   function figure(motion){const pose=motion?a:b;const lines=[[1,2],[1,3,4],[1,5,6],[2,7,8],[2,9,10]];let out='';
     lines.forEach((v,i)=>{const pts=p=>v.map(j=>p[j].join(',')).join(' ');out+=`<polyline class="limb ${i===1||i===3?'backlimb':''}" points="${pts(pose)}">${motion?anim('points',[pts(a),pts(b),pts(b),pts(a)].join(';')):''}</polyline>`;});
     for(const j of [1,2,3,5,7,9])out+=`<circle class="joint" cx="${pose[j][0]}" cy="${pose[j][1]}" r="3.6">${motion?anim('cx',`${a[j][0]};${b[j][0]};${b[j][0]};${a[j][0]}`)+anim('cy',`${a[j][1]};${b[j][1]};${b[j][1]};${a[j][1]}`):''}</circle>`;
     out+=`<circle class="head" cx="${pose[0][0]}" cy="${pose[0][1]}" r="12">${motion?anim('cx',`${a[0][0]};${b[0][0]};${b[0][0]};${a[0][0]}`)+anim('cy',`${a[0][1]};${b[0][1]};${b[0][1]};${a[0][1]}`):''}</circle>`;
     if(e.equipment==='dumbbells')for(const j of (e.id==='goblet-squat'?[4]:[4,6]))out+=`<circle fill="#676767" cx="${pose[j][0]}" cy="${pose[j][1]}" r="6">${motion?anim('cx',`${a[j][0]};${b[j][0]};${b[j][0]};${a[j][0]}`)+anim('cy',`${a[j][1]};${b[j][1]};${b[j][1]};${a[j][1]}`):''}</circle>`;
     if(e.equipment==='bands'){const pts=p=>e.id==='band-chest-press'?`${p[4]} ${p[1][0]-10},${p[1][1]+10} ${p[6]}`:e.id==='band-pull-apart'?`${p[4]} ${p[6]}`:['band-side-step','band-bridge','band-clamshell'].includes(e.id)?`${p[7]} ${p[9]}`:`${p[4]} ${p[8]} ${p[10]} ${p[6]}`;out+=`<polyline class="band" points="${pts(pose)}">${motion?anim('points',[pts(a),pts(b),pts(b),pts(a)].join(';')):''}</polyline>`;}
     return out;}
   const prop=e.id==='chair-squat'?'<path d="M47 101v91m0-48h56v48" stroke="#a9a9a9" stroke-width="4" fill="none"/>':['wall-push-up','narrow-wall-push-up'].includes(e.id)?'<path d="M166 28v164" stroke="#a9a9a9" stroke-width="4"/>':e.id==='wall-sit'?'<path d="M91 48v144" stroke="#a9a9a9" stroke-width="4"/>':'';
   return `<svg class="demo" role="img" aria-label="${esc(e.name)} schematic movement demonstration" viewBox="0 0 210 210"><path class="floor" d="M18 192h174"/>${prop}<g class="${animate?'motion-pose':''}">${figure(animate)}</g>${animate?`<g class="static-pose">${figure(false)}</g>`:''}</svg>`;
 }
 function heading(title,sub,action=''){return `<div class="page-heading"><div><h1 tabindex="-1">${title}</h1><p>${sub}</p></div>${action}</div>`;}
 function statsView(s){return `<div class="stats"><div class="stat">${icon('workout')}<div><strong>${s.workouts}</strong><span>Workouts</span></div></div><div class="stat">${icon('clock')}<div><strong>${s.minutes}</strong><span>Active minutes</span></div></div><div class="stat">${icon('library')}<div><strong>${s.sets}</strong><span>Sets completed</span></div></div></div>`;}
 const nav=[['today','home','Today'],['builder','workout','Build a workout'],['weekly','calendar','Weekly plan'],['library','library','Exercise library'],['progress','progress','Progress'],['profile','profile','My profile']];
 function render(focus=false){
   const requested=location.hash.slice(1);route=['today','builder','library','progress','profile','session','weekly','assessment'].includes(requested)?requested:'today';
   const p=state.profile;
   app.innerHTML=`<aside class="sidebar"><a href="#today" class="brand">${icon('home')}<span>HomeFit</span></a><nav class="nav" aria-label="Main navigation">${nav.map(([r,i,n])=>`<a href="#${r}" class="${route===r?'active':''}" ${route===r?'aria-current="page"':''}>${icon(i)}<span class="nav-label">${n}</span><span class="nav-short">${({today:"Today",builder:"Build",weekly:"Week",library:"Library",progress:"Progress",profile:"Profile"})[r]}</span></a>`).join('')}</nav><div class="sidebar-foot">${icon('shield')}<div><strong>Yours, and only yours.</strong><small>Saved on this device.</small></div></div></aside><main id="main" class="main"><header class="topbar"><div class="mobile-brand">${icon('home')}HomeFit</div><span class="eyeline"><span class="dot"></span> A little space for a stronger you</span><div class="topbar-right"><time>${new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</time><a class="avatar" href="#profile" aria-label="Open my profile">${esc(p.name?p.name[0].toUpperCase():'H')}</a></div></header>${storageError?`<div class="storage-warning" role="alert">${esc(storageError)}</div>`:''}${bandConfirmation(p)?'<div class="notice between"><span>Confirm your band type. Band exercises stay out of new plans until you select the types you own.</span><a href="#profile">Choose band types</a></div>':''}${state.active&&route!=='session'?`<div class="notice between"><span>Your workout is ${state.active.paused?'paused':'in progress'}. Pick up where you left off.</span><a href="#session">Resume workout ${icon('arrow')}</a></div>`:''}<div class="fade-in">${({today:todayView,builder:builderView,library:libraryView,progress:progressView,profile:profileView,session:sessionView,weekly:weeklyView,assessment:assessmentView})[route]()}</div><footer class="footer"><span>HomeFit · Your space. Your pace. Your progress.</span><button data-action="method">How your plan is built</button></footer></main>`;
   if(route==='library')renderLibrary();if(route==='session'){updateClock();restoreDraft();}if(focus)document.querySelector('h1')?.focus({preventScroll:true});
 }
 function go(r){if(location.hash==='#'+r)render();else location.hash=r;}

 function todayView(){const p=state.profile,s=H.stats(state.history),assessment=p.assessment?H.assess(p.assessment):null,week=H.weeklyPlan(p,state.history,state.weeklyPrefs);return `${heading(p.name?`Make today yours, ${esc(p.name)}.`:'A little stronger, every day.','A thoughtful plan. A pace that is yours.')}${!p.configured?`<div class="notice between"><span>Set your goals, equipment, and movement needs.</span><a href="#profile">Set up profile</a></div>`:''}<section class="hero"><div class="hero-copy"><h2>Make time for you.</h2><p>A balanced session, built around your day.</p><div class="metadata"><span>${icon('clock')}${p.minutes} min</span><span>${icon('target')}Full body</span><span>${icon('progress')}${cap(p.level)}</span></div><a href="#builder" class="btn primary">Build my workout ${icon('arrow')}</a></div><div class="hero-art">${demo('squat')}</div></section><div class="between section-title"><h2>Your week, in motion</h2><small>Last 7 days${state.history.some(h=>h.sample)?' · Includes samples':''}</small></div>${statsView(s)}<div class="home-bottom"><section class="panel"><h2>Your week, considered.</h2><div class="mini-week">${week.map(d=>`<div><span>${new Date(d.date+'T12:00:00').toLocaleDateString('en-US',{weekday:'long'})}</span><span class="day-kind ${d.kind==='workout'?'training':''}">${d.kind==='workout'?'Strength':d.kind==='done'?'Completed':d.kind==='review'?'Review needed':'Recovery'}</span></div>`).join('')}</div><a href="#weekly" class="btn ghost">View weekly plan ${icon('arrow')}</a></section><section class="panel assessment-card"><h2>${assessment?assessment.label:'Start where you are.'}</h2><p class="spaced">${assessment?assessment.text:'A two-minute check-in helps us set your starting pace. No timed tests or maximum-effort exercises.'}</p><div class="assessment-art">${icon('profile')}</div><a href="#assessment" class="btn primary">${assessment?'Update assessment':'Take assessment'} ${icon('arrow')}</a></section></div><section class="panel spaced"><h2>Made for your everyday</h2><div class="quick-grid">${[['full','Full-body reset',20],['upper','Upper-body strength',25],['core','Core & control',15]].map(([t,n,m])=>`<button class="quick-row" data-action="quick" data-target="${t}" data-minutes="${m}"><span>${n}<small>${m} minutes · Personalized</small></span>${icon('chevron')}</button>`).join('')}</div></section>`;}
 function assessmentView(){const a=state.profile.assessment;return `${heading('Start where you are.','A simple check-in, not a fitness test.',`<a class="btn secondary" href="#profile">My profile</a>`)}<div class="assessment-layout"><form id="assessment-form" class="panel"><h2>Your current baseline</h2><p class="spaced">Think about your recent everyday experience. No need to perform any movement now.</p>${[['activity','Over the past four weeks, how often have you exercised?',[['none','Rarely or not at all'],['some','About once a week'],['regular','Two or more times a week']]],['movement','How do familiar everyday movements feel?',[['support','I need support or a smaller range'],['comfortable','Comfortable with basic movements'],['confident','Confident with regular strength exercises']]],['recovery','How well are you recovering between active days?',[['low','I often feel tired or sore'],['okay','Usually recovered with a rest day'],['good','Generally fresh and ready']]]].map(([name,title,options])=>`<fieldset class="spaced"><legend>${title}</legend><div class="assessment-options">${options.map(([value,text])=>`<label class="choice"><input type="radio" name="${name}" value="${value}" ${a?.[name]===value?'checked':''} required>${text}</label>`).join('')}</div></fieldset>`).join('')}<div class="notice">Pain is not a fitness level. Use movement restrictions in My profile, and stop any activity that causes pain. This check-in is not medical clearance.</div><p class="error" id="assessment-error" role="alert"></p><button type="submit" class="btn primary">Save assessment ${icon('check')}</button></form><section class="panel soft"><h2>A better starting pace.</h2><ol class="steps"><li>A gentle baseline uses beginner movements, shorter sets, and extra recovery.</li><li>A confident baseline stays within the experience level you selected.</li><li>Your actual exercise check-ins guide future adjustments.</li></ol>${a?`<div class="notice"><strong>${H.assess(a).label}</strong><p>${H.assess(a).text}</p><small>Last updated ${date(a.date)}</small></div>`:''}</section></div>`;}
 function weeklyView(){const prefs=state.weeklyPrefs,week=H.weeklyPlan(state.profile,state.history,prefs),today=H.dayKey(new Date());return `${heading('A week that works for you.','Strength, recovery, and room for real life.')}<div class="weekly-layout"><form id="weekly-form" class="panel"><h2>Your rhythm</h2><label class="field spaced"><span>Training days per week</span><select name="days"><option value="2" ${prefs.days===2?'selected':''}>2 days per week</option><option value="3" ${prefs.days===3?'selected':''}>3 days per week</option></select></label><label class="field"><span>First training weekday</span><select name="startDay">${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((d,i)=>`<option value="${i}" ${prefs.startDay===i?'selected':''}>${d}</option>`).join('')}</select></label><p>Training days are spaced automatically, including across week boundaries. Missed sessions are not stacked onto recovery days.</p><button type="submit" class="btn primary full spaced">Save weekly rhythm</button><p id="weekly-error" class="error" role="alert"></p><div class="notice spaced">${state.profile.minutes} minutes per session · ${state.profile.assessment?H.assess(state.profile.assessment).label:'Based on your profile'}<br><a href="#profile">Edit profile</a> · <a href="#assessment">${state.profile.assessment?'Update':'Take'} assessment</a></div></form><section class="panel"><div class="between"><h2>This week</h2><small>${date(week[0].date+'T12:00:00')} – ${new Date(week[6].date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})}</small></div><div class="week-list">${week.map(d=>`<article class="week-row ${d.date===today?'is-today':''}"><div class="week-date"><strong>${new Date(d.date+'T12:00:00').toLocaleDateString('en-US',{weekday:'short'})}</strong><small>${new Date(d.date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})}</small>${d.date===today?'<span class="tag">Today</span>':''}</div><div class="week-info"><h3><span class="week-dot ${d.kind==='workout'?'training':''}"></span>${d.title}</h3><p>${d.reason}</p>${d.plan?`<small>${Math.ceil(d.plan.seconds/60)} min · ${d.plan.items.length} exercises</small>`:''}</div>${d.kind==='workout'?btn('View session','weekly-open','secondary',`data-date="${d.date}"`):d.kind==='done'?'<a class="btn ghost" href="#progress">View history</a>':d.kind==='review'?'<a class="btn ghost" href="#progress">Review</a>':icon('leaf')}</article>`).join('')}</div><small class="spaced" style="display:block">Starting a scheduled session is available on its date. Preview any day. Recovery adapts to your recent recorded workouts.</small></section></div>`;}

 function builderView(){const p=state.profile;return `${heading('Build your next good habit.','An intentional session. Made for the time and equipment you have.')}<div class="builder"><form id="builder-form" class="panel builder-form"><fieldset><legend>Muscle focus</legend><div class="choices">${['full','upper','lower','core'].map((t,i)=>`<label class="choice"><input type="radio" name="target" value="${t}" ${(state.plan?.target||planIssue?.target||'full')===t?'checked':''}>${label(t)}</label>`).join('')}</div></fieldset><label class="field"><span>Or focus on one muscle group</span><select name="specific"><option value="">Use focus above</option>${['legs','glutes','chest','back','shoulders','arms'].map(t=>`<option value="${t}" ${(state.plan?.target||planIssue?.target)===t?'selected':''}>${label(t)}</option>`).join('')}</select></label><label class="field"><span>Available time</span><select name="minutes">${[10,15,20,25,30,40,45,60].map(m=>`<option value="${m}" ${m===(state.plan?.minutes||planIssue?.minutes||p.minutes)?'selected':''}>${m} minutes</option>`).join('')}</select></label><div class="field"><span>Your equipment</span><p class="readonly">${p.equipment.flatMap(v=>v==='bands'?(p.bandTypes?.length?p.bandTypes.map(label):['Bands: type needed']):[label(v)]).join(' · ')}</p></div><div class="between"><span class="tag">${cap(p.level)}</span><a href="#profile"><small>Update profile</small></a></div><button class="btn primary full spaced" type="submit">Generate workout ${icon('arrow')}</button><p id="builder-error" class="error" role="alert">${esc(planIssue?.message||'')}</p><small>Designed for healthy adults. Use a comfortable range and stop if a movement causes pain.</small></form><section class="panel" id="plan-preview">${planView()}</section></div>`;}
 function planView(){const p=state.plan;if(!p&&planIssue)return unavailableView();if(!p)return `<div class="empty">${icon('leaf')}<h3>A little intention goes a long way.</h3><p>Choose your focus and available time. Your personalized workout will appear here.</p></div><div class="notice">Every plan includes a warm-up, clear sets and reps, rest periods, and a cooldown.</div>`;return `<div class="plan-heading between"><div><h2>Your ${label(p.target).toLowerCase()} session</h2><p>About ${Math.ceil(p.seconds/60)} min · ${p.items.length} exercises · ${p.items.reduce((s,i)=>s+i.sets,0)} sets</p></div>${icon('workout')}</div><div class="notice spaced">${esc(p.adaptation?.text||'Move at your own pace.')}</div><small>${fmt(p.warmup)} warm-up · Main session below · ${fmt(p.cooldown)} cooldown</small>${p.items.map((i,n)=>`<div class="exercise-row"><button class="thumb" data-action="exercise" data-id="${i.id}" aria-label="See ${esc(H.byId(i.id).name)} demonstration">${demo(i.id,false)}</button><div class="desc"><button data-action="exercise" data-id="${i.id}">${H.byId(i.id).name}</button><p>${i.sets} sets × ${i.reps} ${H.byId(i.id).timed?'sec':'reps'} · ${i.rest}s rest</p><p>${i.band?`${equipmentLabel(H.byId(i.id))} · ${cap(i.band)} resistance`:i.load?`${i.load} ${i.unit} per dumbbell · Adjust in session`:equipmentLabel(H.byId(i.id))}</p>${i.advice?`<small>${esc(i.advice)}</small>`:''}</div><button class="icon-btn" data-action="swap" data-index="${n}" aria-label="Swap ${esc(H.byId(i.id).name)}">${icon('swap')}</button></div>`).join('')}<div class="plan-footer"><small>${esc(p.note||'Move with control.')}${p.items.some(i=>i.load)?' Loads use recent comparable resistance when available, otherwise your lightest weight. Adjust before each set.':''}</small><button class="btn primary full" data-action="start">${icon('play')}Start workout</button></div>`;}
 function libraryView(){return `${heading('Find your next move.',`${H.exercises.length} exercises. Clear guidance. A stronger foundation.`)}<div class="filterbar"><label class="search">${icon('search')}<input class="input" id="exercise-search" type="search" aria-label="Search exercises" placeholder="Search exercises or muscles" value="${esc(library.query)}"></label><select class="input" id="muscle-filter" aria-label="Filter by muscle"><option value="all">All muscles</option>${['legs','glutes','chest','back','shoulders','arms','core','cardio'].map(t=>`<option value="${t}" ${library.muscle===t?'selected':''}>${label(t)}</option>`).join('')}</select><select class="input" id="equipment-filter" aria-label="Filter by equipment"><option value="all">All equipment</option>${['bodyweight','bands','long','mini','dumbbells'].map(t=>`<option value="${t}" ${library.equipment===t?'selected':''}>${label(t)}</option>`).join('')}</select></div><div class="between"><small id="library-count" aria-live="polite"></small><label class="inline"><input id="compatible" type="checkbox" ${library.compatible?'checked':''}><small>Matches my profile</small></label></div><div id="library-results" class="library-grid"></div>`;}
 function renderLibrary(){const eligible=new Set(H.eligible(state.profile,state.history).map(e=>e.id));const list=H.exercises.filter(e=>(!library.query||`${e.name} ${e.muscle} ${e.equipment} ${equipmentLabel(e)}`.toLowerCase().includes(library.query.toLowerCase()))&&(library.muscle==='all'||e.muscle===library.muscle)&&(library.equipment==='all'||e.equipment===library.equipment||e.bandType===library.equipment)&&(!library.compatible||eligible.has(e.id)));document.querySelector('#library-count').textContent=`${list.length} exercise${list.length===1?'':'s'}`;document.querySelector('#library-results').innerHTML=list.length?list.map(e=>`<button class="exercise-card" data-action="exercise" data-id="${e.id}"><div class="art">${demo(e.id,false)}</div><div class="card-copy"><h3>${e.name}</h3><p>${label(e.muscle)} · ${equipmentLabel(e)}</p><div class="card-meta"><span class="tag">${['','Beginner','Intermediate','Advanced'][e.level]}</span><small>View form →</small></div></div></button>`).join(''):`<div class="empty" style="grid-column:1/-1">${icon('search')}<h3>No matching movements</h3><p>Try a different search or relax your library filters. Your profile restrictions remain in place for generated workouts.</p>${btn('Clear filters','clear-filters')}</div>`;}
 function profileView(){const p=state.profile;return `${heading('Your starting point.','A plan works better when it starts with you.',`<a class="btn secondary" href="#assessment">${p.assessment?'Update':'Take'} assessment</a>`)}<form id="profile-form"><div class="profile-layout"><section class="panel"><h2>A little about you</h2><label class="field"><span>First name (optional)</span><input name="name" maxlength="40" autocomplete="given-name" value="${esc(p.name)}" placeholder="What should we call you?"></label><div class="field-pair"><label class="field"><span>Body weight</span><input name="weight" type="number" min="${p.unit==='kg'?30:66}" max="${p.unit==='kg'?300:660}" step="0.1" required value="${p.weight}"></label><label class="field"><span>Weight unit</span><select name="unit" id="weight-unit"><option value="kg" ${p.unit==='kg'?'selected':''}>Kilograms (kg)</option><option value="lb" ${p.unit==='lb'?'selected':''}>Pounds (lb)</option></select></label></div><label class="field"><span>Fitness level</span><select name="level">${Object.keys(H.levels).map(l=>`<option value="${l}" ${p.level===l?'selected':''}>${cap(l)}</option>`).join('')}</select><small>Beginner: learning the basics. Intermediate: comfortable with regular training. Advanced: experienced and consistent.</small></label><label class="field"><span>Your main goal</span><select name="goal">${['fitness','strength','endurance'].map(g=>`<option value="${g}" ${p.goal===g?'selected':''}>${label(g)}</option>`).join('')}</select></label><label class="field"><span>Usual workout time</span><select name="minutes">${[10,15,20,25,30,40,45,60].map(m=>`<option value="${m}" ${m===p.minutes?'selected':''}>${m} minutes</option>`).join('')}</select></label><small>Body weight is stored for your reference. It is never used to guess lifting loads or calorie burn.</small></section><div><section class="panel"><h2>Your space, your equipment</h2><fieldset><legend>Available equipment</legend><div class="choices">${['bodyweight','bands','dumbbells','mat'].map(e=>`<label class="choice"><input name="equipment" value="${e}" type="checkbox" ${p.equipment.includes(e)?'checked':''} ${e==='bodyweight'?'disabled':''}>${label(e)}</label>`).join('')}</div></fieldset><fieldset data-band-options ${p.equipment.includes('bands')?'':'hidden'}><legend>Band types you own</legend><div class="choices">${H.bandTypes.map(b=>`<label class="choice"><input type="checkbox" name="bandTypes" value="${b}" ${(p.bandTypes||[]).includes(b)?'checked':''}>${label(b)}</label>`).join('')}</div><small>Long bands: full-length flat bands, tubes, or long loops suitable for the listed movement. Mini loops: short closed loops worn around the legs. Select either or both when Resistance bands is enabled.</small></fieldset><fieldset data-band-options ${p.equipment.includes('bands')?'':'hidden'}><legend>Available band resistance</legend><div class="choices">${H.bandLevels.map(b=>`<label class="choice"><input type="checkbox" name="bandLevels" value="${b}" ${(p.bandLevels||['light']).includes(b)?'checked':''}>${cap(b)}</label>`).join('')}</div><small>Select at least one resistance when using bands. Labels are relative to your own equipment, not standardized weights. Use a level you own for the required band type; follow the manufacturer's stretch limits.</small></fieldset><label class="field"><span>Dumbbell weights, per dumbbell (<span id="load-unit">${p.unit}</span>)</span><input name="weights" value="${p.weights.join(', ')}" placeholder="e.g. 2.5, 5, 10"><small>Separate available weights with commas. A mat is optional comfort equipment; it does not unlock movements.</small></label></section><section class="panel spaced"><h2>Make room for your needs</h2><fieldset><legend>Movement restrictions</legend><div class="choices">${H.restrictions.map(l=>`<label class="choice"><input name="limitations" type="checkbox" value="${l}" ${p.limitations.includes(l)?'checked':''}>${l==='back'?'Back-sensitive':l==='shoulders'?'Shoulder-sensitive':label(l)}</label>`).join('')}</div></fieldset><label class="field"><span>Personal notes (optional)</span><textarea name="notes" maxlength="500" placeholder="Reminders for yourself, or guidance from your clinician">${esc(p.notes)}</textarea><small>Notes are a personal reminder; the app cannot interpret medical conditions. Only the checked restrictions affect exercise selection.</small></label></section></div></div><p id="profile-error" class="error" role="alert"></p><div class="savebar"><button type="submit" class="btn primary">${icon('check')}Save my profile</button></div></form><section class="panel spaced"><h2>Your data stays yours</h2><p class="spaced">Stored in this browser on this device. Export a backup before moving the app, changing browsers, or clearing browser data.</p><div class="settings-row"><div><h3>Backup & restore</h3><p>Backup files contain your profile and workout history. Keep them private.</p></div><div class="inline">${btn('Export','export')}${btn('Import','import')}<input id="import-file" type="file" accept=".json,application/json" hidden></div></div><div class="settings-row"><div><h3>Explore with sample data</h3><p>Add six labeled example sessions. Your own workouts stay intact.</p></div>${btn(state.history.some(h=>h.sample)?'Remove samples':'Load samples',state.history.some(h=>h.sample)?'remove-samples':'samples')}</div><div class="settings-row"><div><h3>Reset this browser</h3><p>Remove the profile, saved plan, and workout history from this browser.</p></div>${btn('Reset data','reset','secondary danger')}</div></section>`;}
 function progressView(){const s=H.stats(state.history),ad=H.feedback(state.history),history=state.history.slice().sort((a,b)=>b.date.localeCompare(a.date));const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-6+i);const end=new Date(d);end.setDate(end.getDate()+1);return {label:d.toLocaleDateString('en-US',{weekday:'short'}),minutes:Math.round(history.filter(h=>h.logs.length&&new Date(h.date)>=d&&new Date(h.date)<end).reduce((n,h)=>n+h.seconds,0)/60)};});const max=Math.max(20,...days.map(d=>d.minutes));return `${heading('Small steps. Real progress.','Every session is a little investment in yourself.',btn('Export data','export'))}${history.some(h=>h.sample)?'<div class="notice warn">Sample sessions are included in these charts and labeled in history. They never influence your coaching recommendations.</div>':''}<div class="between section-title"><h2>Your last 7 days</h2><small>${s.total} total sessions</small></div>${statsView(s)}<div class="grid-2 spaced"><section class="panel"><div class="between"><h2>Time well spent</h2><small>Active minutes</small></div><div class="chart" role="img" aria-label="${days.map(d=>`${d.label}: ${d.minutes} minutes`).join(', ')}">${days.map(d=>`<div class="bar-col"><span class="bar-value">${d.minutes||''}</span><div class="bar" style="height:${Math.max(2,d.minutes/max*105)}px"></div><small>${d.label}</small></div>`).join('')}</div></section><section class="panel soft"><h2>Your next step</h2><div class="coach">${icon('leaf')}<p>${esc(ad.text)}</p></div><a href="#builder" class="btn ghost spaced">Build your next workout ${icon('arrow')}</a></section></div><section class="panel spaced"><div class="between"><h2>Workout history</h2><small>${history.length} saved</small></div><div class="history-list">${history.length?history.map(h=>`<div class="history-row"><div><div class="inline"><button class="title" data-action="history" data-id="${esc(h.id)}">${label(h.target)} ${h.completion>=1?'session':'session · Partial'}</button>${h.sample?'<span class="tag sample">Sample</span>':''}</div><p>${date(h.date)} · ${Math.round(h.seconds/60)} min · ${h.logs.length} sets · ${Math.round(h.completion*100)}% complete</p></div><button class="icon-btn" data-action="history" data-id="${esc(h.id)}" aria-label="View ${label(h.target)} workout from ${date(h.date)}">${icon('chevron')}</button></div>`).join(''):`<div class="empty">${icon('progress')}<h3>Your story starts with one session.</h3><p>Complete a workout to see your progress, or explore with clearly labeled sample sessions.</p><div class="inline" style="justify-content:center"><a class="btn primary" href="#builder">Build a workout</a>${btn('Load samples','samples')}</div></div>`}</div></section>`;}
 function phaseDuration(a){return a.phase==='warmup'?a.plan.warmup:a.phase==='cooldown'?a.plan.cooldown:a.phase==='rest'?a.plan.items[a.index].rest:H.byId(a.plan.items[a.index].id).timed?a.plan.items[a.index].reps:0;}
 function sessionView(){const a=state.active;if(!a)return `${heading('Your next session awaits.','Build a workout, then take it one set at a time.')}<div class="empty">${icon('workout')}<a href="#builder" class="btn primary">Build a workout</a></div>`;if(a.phase==='review')return reviewView();const item=a.plan.items[a.phase==='rest'?a.nextIndex:a.index],e=H.byId(item.id),work=a.phase==='work',rest=a.phase==='rest';return `${heading('One set at a time.','Focus on good form. Make it count.',`<span class="tag">${label(a.plan.target)} · <span id="elapsed">${fmt(a.elapsed)}</span></span>`)}${H.pendingEquipment(a,state.profile).length?'<div class="notice" role="alert">This saved workout needs equipment you have not selected. <a href="#profile">Confirm your band types</a> to resume, or use End session to save completed sets and build a new workout.</div>':''}${recovered?'<div class="notice">Your session was restored and paused. Resume when you are ready; time away is not counted.</div>':''}<div class="session-progress" aria-label="Exercise ${a.index+1} of ${a.plan.items.length}">${a.plan.items.map((_,i)=>`<span class="${i<a.index?'done':i===a.index?'current':''}"></span>`).join('')}</div><div class="session-grid"><section>${work||rest?`<div class="work-art">${demo(e.id,work&&!a.paused)}<div class="demo-label">Schematic movement guide · Read the form cues below</div></div><div class="session-copy"><small>${rest?'UP NEXT':'EXERCISE '+(a.index+1)+' OF '+a.plan.items.length}</small><h2>${e.name}</h2><p>${equipmentLabel(e)}</p><ol class="steps">${e.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="cue">${e.cue}</div>${state.profile.notes?`<div class="notice spaced">Your reminder: ${esc(state.profile.notes)}</div>`:''}</div>`:`<div class="work-art phase-copy"><div class="phase-icon">${icon(a.phase==='warmup'?'leaf':'check')}</div><h2>${a.phase==='warmup'?'Arrive in your body.':'Bring it back to calm.'}</h2><p>${a.phase==='warmup'?'Begin with comfortable walking or gentle seated movement. Add small shoulder rolls and easy joint movements only where comfortable. Gradually ease into your session.':'Slow your breathing. Walk gently or sit comfortably. Add easy stretches if they feel good, without forcing the range.'}</p></div><div class="cue spaced">Stop if you feel pain, dizziness, or unusual shortness of breath. This app is for general fitness, not injury rehabilitation.</div>`}</section><section class="panel timer-panel"><div class="timer-caption">${a.phase==='warmup'?'Warm-up':a.phase==='cooldown'?'Cooldown':rest?'Rest & reset':e.timed?'Hold timer':'Move at your own pace'}</div><div class="timer" id="session-timer">${fmt(a.remaining)}</div><div class="timer-caption" id="timer-status">${a.paused?'Paused':work&&!e.timed?'Complete the reps below, then log your set.':'Breathe. You have this.'}</div><div class="timer-track"><div id="timer-fill"></div></div>${work?`<h3>Set ${a.set} of ${item.sets}</h3><div class="set-dots">${Array.from({length:item.sets},(_,i)=>`<span class="set-dot ${i<a.set-1?'done':''}"></span>`).join('')}</div><div class="session-inputs"><label class="field"><span>${e.timed?'Seconds held':'Reps completed'}</span><input id="actual-reps" type="number" min="1" max="500" step="1" value="${item.reps}" ${a.paused?'disabled':''}></label><label class="field"><span>${e.equipment==='dumbbells'?`Load / dumbbell (${item.unit})`:'Resistance'}</span>${e.equipment==='dumbbells'?`<input id="actual-load" type="number" min="0.1" max="200" step="0.1" value="${item.load}" ${a.paused?'disabled':''}>`:e.equipment==='bands'?`<select id="actual-band" ${a.paused?'disabled':''}>${(state.profile.bandLevels||['light']).map(b=>`<option value="${b}" ${b===(item.band||'light')?'selected':''}>${cap(b)}</option>`).join('')}</select>`:`<input aria-label="Resistance" value="Bodyweight" readonly>`}</label></div><label class="field set-feedback"><span>How did this set feel?</span><select id="set-feedback" ${a.paused?'disabled':''}><option value="right">Just right</option><option value="easy">Too easy</option><option value="hard">Too hard</option><option value="pain">Pain / discomfort — stop</option></select></label><button class="btn primary full" data-action="complete-set" ${a.paused?'disabled':''}>${icon('check')}Complete set</button>`:`<button class="btn primary full" data-action="next-phase" ${a.paused?'disabled':''}>${rest?'Skip rest':a.phase==='warmup'?'Ready to start':'Finish cooldown'} ${icon('arrow')}</button>`}<button class="btn secondary full" data-action="pause">${icon(a.paused?'play':'pause')}${a.paused?'Resume':'Pause'}</button><button class="btn ghost full" data-action="end">End session</button><button class="btn ghost danger full" data-action="pain">I feel pain — stop</button><small class="spaced" style="display:block">${work?'Log only the reps or seconds you actually complete.':''}</small></section></div>`;}

 function reviewView(){const a=state.active,total=a.plan.items.reduce((n,i)=>n+i.sets,0),ids=[...new Set([...a.logs.map(l=>l.id),...(a.painExercise?[a.painExercise]:[])])];return `${heading('Every check-in counts.','Reflect on each movement. Make your next plan more personal.')}<form id="review-form" class="panel review"><div class="success-icon">${icon('check')}</div><div class="center"><h2>${a.logs.length?'You showed up for yourself.':'Listen to your body.'}</h2><p class="spaced">${a.logs.length} of ${total} sets · ${fmt(a.elapsed)} active time · ${label(a.plan.target)}</p></div>${a.budgetReached?'<div class="notice spaced">Your selected active-time limit has been reached. Completed sets are kept. You can cool down gently outside the recorded session.</div>':''}${a.pain?'<div class="notice warn spaced">You stopped for discomfort. Pain reports stay attached to the affected movement until you resolve them in Progress.</div>':''}<fieldset><legend class="spaced">Overall, how did this session feel?</legend><div class="feedback-choices">${[['easy','Too easy'],['right','Just right'],['hard','Too hard'],['pain','Pain / discomfort']].map(([v,l])=>`<label><input type="radio" name="feedback" value="${v}" ${(a.pain?'pain':'right')===v?'checked':''} ${a.pain&&v!=='pain'?'disabled':''} required>${l}</label>`).join('')}</div></fieldset><h3>Movement check-ins</h3><p><small>Choose Pain only for the affected movements. If you cannot identify a movement, select general discomfort below.</small></p>${ids.map(id=>{const logs=a.logs.filter(l=>l.id===id),locked=a.painExercise===id||logs.some(l=>l.feedback==='pain'),rating=locked?'pain':logs.some(l=>l.feedback==='hard')?'hard':logs.length&&logs.every(l=>l.feedback==='easy')?'easy':'right';return `<label class="feedback-row"><span>${H.byId(id).name}</span><select name="exercise-${id}" ${locked?'disabled':''}>${[['right','Just right'],['easy','Too easy'],['hard','Too hard'],['pain','Pain / discomfort']].map(([v,l])=>`<option value="${v}" ${v===rating?'selected':''}>${l}</option>`).join('')}</select></label>`;}).join('')}<label class="choice spaced"><input type="checkbox" name="generalPain" ${a.generalPain?'checked disabled':''}>General discomfort / unsure which movement</label><div class="notice spaced">Each movement adapts separately. Two comfortable completed sessions can increase its reps. Difficult movements get less volume. Unknown pain pauses new planning until you review it.</div><label class="field"><span>Reflection (optional)</span><textarea name="notes" maxlength="500" placeholder="What felt good? What would you change?">${esc(a.note||'')}</textarea></label><div class="inline"><button class="btn primary" type="submit">Save workout ${icon('check')}</button>${btn('Discard session','discard','ghost')}</div><p id="review-error" class="error" role="alert"></p></form>`;}

 function openModal(html){lastFocus=document.activeElement;modal.innerHTML=`<button class="icon-btn close" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button>${html}`;if(!modal.open)modal.showModal();modal.querySelector('h2')?.setAttribute('tabindex','-1');modal.querySelector('h2')?.focus();}
 function closeModal(){modal.close();lastFocus?.focus?.();}
 function exerciseModal(id){const e=H.byId(id);if(!e)return;const matches=H.eligible(state.profile,state.history),compatible=matches.some(x=>x.id===id),alts=e.alternatives.filter(id=>matches.some(x=>x.id===id));openModal(`<h2>${e.name}</h2><p>${label(e.muscle)} · ${equipmentLabel(e)} · ${['','Beginner','Intermediate','Advanced'][e.level]}</p><div class="modal-art">${demo(id)}<div class="demo-label">Schematic movement guide · Not a medical assessment</div></div>${!compatible?'<div class="notice warn">This exercise does not match your current level, equipment, restrictions, or pain feedback. It will not appear in your generated plans.</div>':''}<h3>How to do it</h3><ol class="steps">${e.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="cue">${e.cue}</div><h3 class="spaced">Explore alternatives</h3><p><small>Alternatives match your equipment, level, restrictions, and pain feedback. Review their guidance first.</small></p><div class="inline spaced">${alts.length?alts.map(id=>btn(H.byId(id).name,'exercise','secondary',`data-id="${id}"`)).join(''):'<small>No compatible alternatives are available for your profile.</small>'}</div>`);}
 function methodModal(){openModal(`<h2>Thoughtful rules. No AI required.</h2><p>HomeFit uses transparent, deterministic rules for general adult fitness.</p><ol class="steps"><li>Filter by muscle focus, equipment, experience, movement restrictions, and recorded pain feedback.</li><li>Choose varied movement patterns. Fit conservative sets, repetitions, rests, a warm-up, and a cooldown into your time budget.</li><li>Use your assessment and movement check-ins to hold steady, reduce volume, or gently increase repetitions for that exercise. Never guess a heavy load from your body weight.</li></ol><h3>Evidence & boundaries</h3><p>CDC guidance recommends muscle-strengthening activity on at least two days a week, alongside aerobic activity. ACSM guidance supports gradual progression and individualized resistance training.</p><p>The exact filters, time estimates, weekly spacing, and feedback thresholds are HomeFit product heuristics, not clinically validated prescriptions. This app does not diagnose injuries or replace a qualified trainer or clinician.</p><div class="inline spaced"><a target="_blank" rel="noopener noreferrer" href="https://www.cdc.gov/physical-activity-basics/guidelines/adults.html">CDC activity guidance ↗</a><a target="_blank" rel="noopener noreferrer" href="https://acsm.org/resistance-training-guidelines-update-2026/">ACSM 2026 guidance ↗</a></div><p class="spaced"><small>Opening these references visits external websites. The app itself makes no network requests.</small></p>`);}
 function historyModal(id){const h=state.history.find(h=>h.id===id);if(!h)return;openModal(`<h2>${label(h.target)} session</h2><p>${date(h.date)} · ${fmt(h.seconds)} active time · ${Math.round(h.completion*100)}% complete</p><div class="notice spaced">Check-in: ${h.feedback==='right'?'Just right':h.feedback==='pain'?'Pain / discomfort':h.feedback==='easy'?'Too easy':'Too hard'}${h.sample?' · Sample data':''}</div>${h.notes?`<p>${esc(h.notes)}</p>`:''}${h.painResolvedAt?`<div class="notice">Pain report resolved ${date(h.painResolvedAt)}. Original feedback retained.</div>`:''}${h.exerciseFeedback?`<div class="spaced">${Object.entries(h.exerciseFeedback).map(([id,r])=>`<p>${H.byId(id).name}: ${r==='right'?'Just right':r==='pain'?'Pain / discomfort':r==='easy'?'Too easy':'Too hard'}</p>`).join('')}</div>`:''}<div class="table-wrap"><table class="history-detail"><thead><tr><th>Exercise</th><th>Actual reps / sec</th><th>Load</th></tr></thead><tbody>${h.logs.map(l=>`<tr><td>${H.byId(l.id).name}</td><td>${l.reps}${H.byId(l.id).timed?'s':''}</td><td>${l.band?`${equipmentLabel(H.byId(l.id))} · ${cap(l.band)}`:l.load?`${l.load} ${l.unit}`:'—'}</td></tr>`).join('')}</tbody></table></div>${(H.painStatus([h]).general||H.painStatus([h]).excluded.length)&&!h.painResolvedAt?`<p class="spaced">Pain feedback keeps these movements out of future plans. Clear it only after you have resolved the cause and are comfortable returning.</p>${btn('Clear pain feedback','clear-pain','secondary',`data-id="${esc(id)}"`)}`:''}<div class="modal-actions">${btn('Delete session','delete-history','secondary danger',`data-id="${esc(id)}"`)}</div>`);}
 function confirmModal(title,text,action,extra='',danger=false){openModal(`<h2>${title}</h2><p class="spaced">${text}</p><div class="modal-actions">${btn('Cancel','close-modal')}${btn('Confirm',action,danger?'danger-bg':'primary',extra)}</div>`);}
 function unavailableView(){const e=planIssue;return `<div class="empty">${icon('info')}<h3>${e.code==='NO_EXERCISES'?'A different focus may fit.':'Your plan needs a review.'}</h3><p>${esc(e.message)}</p><div class="inline spaced">${(e.availableTargets||[]).slice(0,4).map(t=>btn('Try '+label(t).toLowerCase(),'available-focus','secondary',`data-target="${t}" data-minutes="${e.minutes}"`)).join('')}<a class="btn secondary" href="#${H.feedback(state.history).needsReview?'progress':'profile'}">${H.feedback(state.history).needsReview?'Review feedback':'Edit profile'}</a></div></div>`;}
 function makePlan(target,minutes){try{state.plan=H.generate(state.profile,state.history,{target,minutes,seed:seed++});planIssue=null;save();return true;}catch(e){state.plan=null;planIssue={message:e.message,code:e.code,availableTargets:e.availableTargets,target,minutes};save();const err=document.querySelector('#builder-error'),preview=document.querySelector('#plan-preview');if(err)err.textContent=e.message;if(preview)preview.innerHTML=unavailableView();return false;}}
 function setPhase(phase,seconds){const a=state.active;a.draft=null;a.phase=phase;a.remaining=seconds;a.phaseTotal=seconds;a.deadline=a.paused?null:Date.now()+seconds*1000;a.lastTick=Date.now();save();render();}
 function start(){if(state.active){confirmModal('A workout is already in progress.','Resume your current session, or end it from the workout screen before starting another.','resume-session');return;}if(!state.plan)return;try{H.checkPlan(state.plan,state.profile,state.history);}catch(err){toast(err.message);return;}const now=Date.now();state.active={id:H.uid(),plan:JSON.parse(JSON.stringify(state.plan)),index:0,set:1,phase:'warmup',remaining:state.plan.warmup,phaseTotal:state.plan.warmup,deadline:now+state.plan.warmup*1000,lastTick:now,elapsed:0,paused:false,logs:[],started:new Date().toISOString(),pain:false,scheduledDate:state.plan.scheduledDate||null};save();recovered=false;go('session');}
 function nextPhase(){const a=state.active;if(!a||a.paused||!confirmSessionEquipment())return;if(!syncClock())return;if(a.phase==='warmup')setPhase('work',H.byId(a.plan.items[0].id).timed?a.plan.items[0].reps:0);else if(a.phase==='rest'){if(a.nextIndex!==undefined){a.index=a.nextIndex;a.set=a.nextSet;delete a.nextIndex;delete a.nextSet;}const item=a.plan.items[a.index];setPhase('work',H.byId(item.id).timed?item.reps:0);}else if(a.phase==='cooldown')toReview();}

 function captureDraft(){const a=state.active;if(!a||a.phase!=='work'||!document.querySelector('#actual-reps'))return;const draft={};for(const id of ['actual-reps','actual-load','actual-band','set-feedback']){const el=document.getElementById(id);if(el)draft[id]=el.value;}a.draft=draft;}
 function restoreDraft(){const a=state.active;if(!a?.draft||a.phase!=='work')return;for(const id of ['actual-reps','actual-load','actual-band','set-feedback']){const el=document.getElementById(id);if(el&&typeof a.draft[id]==='string')el.value=a.draft[id];}}
 function syncClock(){const a=state.active;if(!a||a.phase==='review')return false;if(a.paused)return true;const now=Date.now(),delta=Math.max(0,(now-(a.lastTick||now))/1000);a.elapsed=Math.min(a.plan.minutes*60,a.elapsed+delta);a.lastTick=now;if(a.deadline)a.remaining=Math.max(0,Math.ceil((a.deadline-now)/1000));if(a.elapsed>=a.plan.minutes*60){a.paused=true;a.deadline=null;a.phase='review';a.budgetReached=true;save();render();return false;}return true;}

 function confirmSessionEquipment(){const a=state.active;if(!H.pendingEquipment(a,state.profile).length)return true;a.paused=true;a.deadline=null;save();render();toast('Confirm the required band types in My profile, or end this session to save completed sets.');return false;}
 function pause(){captureDraft();const a=state.active;if(!a||a.phase==='review')return;if(a.paused&&!confirmSessionEquipment())return;if(!syncClock())return;a.paused=!a.paused;a.lastTick=Date.now();a.deadline=a.paused?null:Date.now()+a.remaining*1000;recovered=false;save();render();}
 function completeSet(){const a=state.active;if(!a||a.paused||a.phase!=='work'||!confirmSessionEquipment())return;const item=a.plan.items[a.index],reps=Number(document.querySelector('#actual-reps').value),load=H.byId(item.id).equipment==='dumbbells'?Number(document.querySelector('#actual-load').value):0;if(!Number.isInteger(reps)||reps<1||reps>500||!Number.isFinite(load)||load<0||load>200||(H.byId(item.id).equipment==='dumbbells'&&load===0)){toast('Enter 1–500 completed reps or seconds, and a valid positive dumbbell load up to 200.');return;}if(!syncClock())return;const rating=document.querySelector('#set-feedback').value,band=H.byId(item.id).equipment==='bands'?document.querySelector('#actual-band').value:null;a.logs.push({id:item.id,reps,load,unit:item.unit,set:a.set,feedback:rating,band});item.load=load;if(band)item.band=band;if(rating==='pain'){a.painExercise=item.id;toReview(true);return;}if(a.set<item.sets){a.nextIndex=a.index;a.nextSet=a.set+1;setPhase('rest',item.rest);}else if(a.index<a.plan.items.length-1){a.nextIndex=a.index+1;a.nextSet=1;setPhase('rest',item.rest);}else setPhase('cooldown',a.plan.cooldown);}
 function toReview(pain=false){syncClock();const a=state.active;a.paused=true;a.deadline=null;a.phase='review';a.pain=!!pain;save();go('session');render();}
 function updateClock(){const a=state.active;if(!a||a.phase==='review')return;const item=a.plan.items[a.index],e=H.byId(item.id),timer=document.querySelector('#session-timer');if(timer)timer.textContent=a.phase==='work'&&!e.timed?fmt(a.elapsed):fmt(a.remaining);const elapsed=document.querySelector('#elapsed');if(elapsed)elapsed.textContent=fmt(a.elapsed);const bar=document.querySelector('#timer-fill');if(bar)bar.style.width=`${a.phase==='work'&&!e.timed?0:Math.max(0,Math.min(100,100*(1-a.remaining/(a.phaseTotal||phaseDuration(a)||1))))}%`;const status=document.querySelector('#timer-status');if(status)status.textContent=a.paused?'Paused':a.remaining===0&&a.phase==='work'&&e.timed?'Time reached. Log the seconds you actually held.':a.phase==='work'&&!e.timed?'Complete the reps below, then log your set.':'Breathe. You have this.';}
 let tickCount=0;setInterval(()=>{const a=state.active;if(!a||a.paused||a.phase==='review')return;if(!syncClock())return;if(a.remaining===0&&['warmup','rest','cooldown'].includes(a.phase))nextPhase();if(route==='session')updateClock();if(++tickCount%4===0)save();},250);
 document.addEventListener('visibilitychange',()=>{if(document.hidden)captureDraft();if(document.hidden&&state.active&&!state.active.paused&&state.active.phase!=='review'){syncClock();state.active.paused=true;state.active.deadline=null;save();render();}});
 window.addEventListener('pagehide',()=>{if(state.active){syncClock();state.active.paused=true;state.active.deadline=null;}save();});
 window.addEventListener('hashchange',()=>{render(true);window.scrollTo(0,0);});
 window.addEventListener('storage',e=>{if(e.key===KEY){writeBlocked=true;storageError='HomeFit data changed in another tab. Export any unsaved work, then reload this tab before making more changes.';if(state.active){state.active.paused=true;state.active.deadline=null;}render();}});
 document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,fd=new FormData(form);if(form.id==='assessment-form'){try{if(state.active)throw Error('Finish or discard your current workout before updating the assessment.');const assessment={activity:fd.get('activity'),movement:fd.get('movement'),recovery:fd.get('recovery'),date:new Date().toISOString()};H.assess(assessment);state.profile.assessment=assessment;state.plan=null;planIssue=null;save();render();toast('Assessment saved. Your next plan will use this starting pace.');}catch(err){document.querySelector('#assessment-error').textContent=err.message;}}else if(form.id==='weekly-form'){const prefs={days:Number(fd.get('days')),startDay:Number(fd.get('startDay'))};try{H.weeklyPlan(state.profile,state.history,prefs);state.weeklyPrefs=prefs;save();render();toast('Weekly rhythm saved. Recovery days are included.');}catch(err){document.querySelector('#weekly-error').textContent=err.message;}}else if(form.id==='builder-form'){if(makePlan(fd.get('specific')||fd.get('target')||'full',Number(fd.get('minutes')))){render();toast('Your workout is ready.');}}else if(form.id==='profile-form'){try{const raw=fd.get('weights').trim();const p={name:fd.get('name').trim(),weight:Number(fd.get('weight')),unit:fd.get('unit'),level:fd.get('level'),goal:fd.get('goal'),minutes:Number(fd.get('minutes')),equipment:['bodyweight',...fd.getAll('equipment').filter(v=>v!=='bodyweight')],weights:raw?[...new Set(raw.split(',').map(s=>Number(s.trim())))].sort((a,b)=>a-b):[],limitations:fd.getAll('limitations'),notes:fd.get('notes').trim(),configured:true,bandLevels:fd.getAll('bandLevels').length?fd.getAll('bandLevels'):['light'],bandTypes:fd.getAll('bandTypes'),assessment:state.profile.assessment};H.validateProfile(p);if(p.equipment.includes('bands')&&!p.bandTypes.length)throw Error('Select a long resistance band, a mini loop band, or both.');if(p.equipment.includes('bands')&&!fd.getAll('bandLevels').length)throw Error('Choose at least one band resistance.');if(state.active){const changed=Object.keys(p).some(k=>!['bandTypes','configured'].includes(k)&&JSON.stringify(p[k])!==JSON.stringify(state.profile[k]));if(changed)throw Error('Only band types can be updated during an active workout. Finish or save that workout before changing other preferences.');syncClock();state.active.paused=true;state.active.deadline=null;state.active.lastTick=Date.now();state.active.plan.profileSignature=JSON.stringify(p);}state.profile=p;state.plan=null;planIssue=null;save();render();toast('Profile saved. Your next workout will use these preferences.');}catch(err){document.querySelector('#profile-error').textContent=err.message;}}else if(form.id==='review-form'){const a=state.active;if(!a)return;const ids=[...new Set([...a.logs.map(l=>l.id),...(a.painExercise?[a.painExercise]:[])])],exerciseFeedback={};ids.forEach(id=>{exerciseFeedback[id]=a.painExercise===id||a.logs.some(l=>l.id===id&&l.feedback==='pain')?'pain':fd.get(`exercise-${id}`)||'right';});const painExercises=ids.filter(id=>exerciseFeedback[id]==='pain'),generalPain=!!a.generalPain||fd.has('generalPain');let feedback=fd.get('feedback');if(a.pain||painExercises.length||generalPain)feedback='pain';if(feedback==='pain'&&!painExercises.length&&!generalPain){document.querySelector('#review-error').textContent='Mark the affected movement as Pain, or select general discomfort.';return;}if(!['easy','right','hard','pain'].includes(feedback))return;const total=a.plan.items.reduce((n,i)=>n+i.sets,0);if(!state.history.some(h=>h.id===a.id))state.history.push({id:a.id,date:new Date().toISOString(),target:a.plan.target,seconds:Math.round(a.elapsed),completion:a.logs.length/total,feedback,notes:fd.get('notes').trim(),logs:a.logs,painExercises,generalPain,exerciseFeedback,scheduledDate:a.scheduledDate||null,sample:false});state.active=null;state.plan=null;save();go('progress');toast('Workout saved. Your next plan will reflect each movement check-in.');}});

 document.addEventListener('input',e=>{if(['actual-reps','actual-load','actual-band','set-feedback'].includes(e.target.id)){captureDraft();save();}if(e.target.id==='exercise-search'){library.query=e.target.value;renderLibrary();}});
 document.addEventListener('change',async e=>{const el=e.target;if(el.name==='equipment'&&el.value==='bands')document.querySelectorAll('[data-band-options]').forEach(f=>f.hidden=!el.checked);if(['actual-band','set-feedback'].includes(el.id)){captureDraft();save();}if(el.id==='muscle-filter'){library.muscle=el.value;renderLibrary();}if(el.id==='equipment-filter'){library.equipment=el.value;renderLibrary();}if(el.id==='compatible'){library.compatible=el.checked;renderLibrary();}if(el.id==='weight-unit'){const form=el.form,old=form.elements.weight.min==='30'?'kg':'lb';if(old!==el.value){const factor=el.value==='lb'?2.2046226218:1/2.2046226218;form.elements.weight.value=(Number(form.elements.weight.value)*factor).toFixed(1);form.elements.weights.value=form.elements.weights.value.split(',').map(v=>v.trim()?+(Number(v)*factor).toFixed(1):'').join(', ');form.elements.weight.min=el.value==='kg'?30:66;form.elements.weight.max=el.value==='kg'?300:660;document.querySelector('#load-unit').textContent=el.value;}}if(el.name==='target'&&el.form?.id==='builder-form')el.form.elements.specific.value='';if(el.form?.id==='builder-form'&&['target','specific','minutes'].includes(el.name)){state.plan=null;planIssue=null;save();document.querySelector('#builder-error').textContent='';document.querySelector('#plan-preview').innerHTML=planView();}if(el.id==='import-file'){const file=el.files[0];if(!file)return;try{if(file.size>8e6)throw Error('Choose a HomeFit backup smaller than 8 MB.');const parsed=H.loadState(JSON.parse(await file.text()));pendingImport=parsed;confirmModal('Restore this backup?','This replaces the profile and workout history in this browser. Export your current data first if you want to keep it.','confirm-import');}catch(err){toast(`Could not import: ${err.message}`);}el.value='';}});
 let pendingImport=null;
 function download(content,name){const blob=new Blob([content],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
 document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;
   if(action==='close-modal')closeModal();
   else if(action==='exercise')exerciseModal(id);
   else if(action==='method')methodModal();
   else if(action==='available-focus'){if(makePlan(el.dataset.target,Number(el.dataset.minutes)))render();}
   else if(action==='quick'){makePlan(el.dataset.target,Number(el.dataset.minutes));go('builder');}
   else if(action==='clear-filters'){library={query:'',muscle:'all',equipment:'all',compatible:false};render();}
   else if(action==='swap'){const n=Number(el.dataset.index),item=state.plan.items[n],alts=H.alternatives(item,state.profile,state.history,state.plan);openModal(`<h2>A different way to move.</h2><p>Alternatives for ${H.byId(item.id).name}, filtered for your profile.</p><div class="spaced">${alts.length?alts.map(a=>`<button class="quick-row" data-action="choose-swap" data-index="${n}" data-id="${a.id}"><span>${a.name}<small>${equipmentLabel(a)} · ${label(a.muscle)}</small></span>${icon('arrow')}</button>`).join(''):'<div class="notice">No other compatible exercise for this muscle group is available. Try a different focus or review your equipment.</div>'}</div>`);}
   else if(action==='choose-swap'){try{state.plan=H.replaceExercise(state.plan,Number(el.dataset.index),id,state.profile,state.history);save();closeModal();render();toast('Exercise replaced. Timing and resistance updated.');}catch(err){toast(err.message);}}

   else if(action==='weekly-open'){const d=H.weeklyPlan(state.profile,state.history,state.weeklyPrefs).find(d=>d.date===el.dataset.date);if(!d?.plan){toast('This day now needs recovery or review.');render();return;}openModal(`<h2>${d.title}</h2><p>${date(d.date+'T12:00:00')} · About ${Math.ceil(d.plan.seconds/60)} minutes</p><div class="spaced">${d.plan.items.map(i=>`<div class="quick-row"><span>${H.byId(i.id).name}<small>${i.sets} sets × ${i.reps} ${H.byId(i.id).timed?'seconds':'reps'} · ${i.rest}s rest${i.band?' · '+equipmentLabel(H.byId(i.id))+' · '+cap(i.band):''}</small></span></div>`).join('')}</div><div class="modal-actions">${d.date===H.dayKey(new Date())?btn('Use this session','weekly-use','primary',`data-date="${d.date}"`):'<p>Preview only. Start this session on its scheduled date, or build a separate workout.</p>'}</div>`);}
   else if(action==='weekly-use'){if(state.active){toast('Finish your active session before starting another.');return;}const d=H.weeklyPlan(state.profile,state.history,state.weeklyPrefs).find(d=>d.date===el.dataset.date);if(d?.kind!=='workout'||d.date!==H.dayKey(new Date())){toast('The schedule changed. Review your week again.');closeModal();render();return;}state.plan={...d.plan,scheduledDate:d.date};save();closeModal();go('builder');}
   else if(action==='start')start();
   else if(action==='resume-session'){closeModal();go('session');}
   else if(action==='pause')pause();
   else if(action==='complete-set')completeSet();
   else if(action==='next-phase')nextPhase();
   else if(action==='end'){if(!state.active.paused)pause();confirmModal('Finish your session early?','Your completed sets will be kept. You can review your check-in and save this as a partial workout.','confirm-end');}
   else if(action==='confirm-end'){closeModal();toReview();}
   else if(action==='pain'){const a=state.active;if(!a)return;if(a.phase==='work'){a.painExercise=a.plan.items[a.index].id;a.note=`Stopped because of discomfort during ${H.byId(a.painExercise).name}.`;}else{a.generalPain=true;a.note='Stopped because of general discomfort outside an active exercise.';}toReview(true);}
   else if(action==='discard')confirmModal('Discard this session?','This removes the current session and its unsaved sets. Your earlier workout history stays intact.','confirm-discard','',true);
   else if(action==='confirm-discard'){state.active=null;save();closeModal();go('today');toast('Session discarded.');}
   else if(action==='history')historyModal(id);
   else if(action==='delete-history')confirmModal('Delete this saved session?','This removes this session from your history and coaching feedback. Export a backup first if you want to keep a copy.','confirm-delete',`data-id="${esc(id)}"`,true);
   else if(action==='confirm-delete'){state.history=state.history.filter(h=>h.id!==id);state.plan=null;save();closeModal();render();toast('Session deleted.');}
   else if(action==='clear-pain')confirmModal('Clear this pain feedback?','This marks the pain report for this session resolved and preserves the original check-in. Movements remain excluded if another unresolved report flags them. Proceed only after addressing the discomfort.','confirm-clear-pain',`data-id="${esc(id)}"`);
   else if(action==='confirm-clear-pain'){const h=state.history.find(h=>h.id===id);h.painResolvedAt=new Date().toISOString();state.plan=null;save();closeModal();render();toast('Pain report marked resolved. Original feedback stays in your history.');}
   else if(action==='samples'){state.history.push(...H.sample().filter(h=>!state.history.some(x=>x.id===h.id)));save();render();toast('Six sample sessions added. Your own workouts are unchanged.');}
   else if(action==='remove-samples'){state.history=state.history.filter(h=>!h.sample);save();render();toast('Sample sessions removed.');}
   else if(action==='export'){let content=JSON.stringify(state,null,2);if(writeBlocked){try{content=localStorage.getItem(KEY)||content;}catch{}}download(content,`homefit-backup-${new Date().toISOString().slice(0,10)}.json`);toast('Backup exported. Keep it in a private place.');}
   else if(action==='import'){if(state.active){toast('Finish or discard the current workout before importing a backup.');return;}document.querySelector('#import-file').click();}
   else if(action==='confirm-import'){state=pendingImport;pendingImport=null;planIssue=null;if(state.active){state.active.paused=true;state.active.deadline=null;state.active.lastTick=Date.now();recovered=true;}writeBlocked=false;save();closeModal();render();toast('Backup restored.');}
   else if(action==='reset')confirmModal('Reset all HomeFit data?','This clears your profile and history from this browser. Export a backup before continuing; this cannot be undone here.','confirm-reset','',true);
   else if(action==='confirm-reset'){try{localStorage.removeItem('homefit.v1.pre-v2');}catch{}state=H.fresh();planIssue=null;writeBlocked=false;save();closeModal();go('today');toast('HomeFit has been reset.');}
 });
 modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
 modal.addEventListener('cancel',()=>lastFocus?.focus?.());
 render();
})();
